// Solve linear assignment problem for n x n cost matrix a (row-major, double).
// Returns assignment: rowsol[i] = column assigned to row i.
// colsol[j] = row assigned to column j.
// u, v are dual variables (optional output).
void lapjv(int n, const double *a, int *rowsol, int *colsol, double *u, double *v)
{
    int i, j, k, imin, numfree, f, i0, j1, j2, endofpath, last, low, up;
    double min, h, umin, usubmin, v2;
