            if (a[i*n + j] < min) {
                min = a[i*n + j];
                imin = i;
            }
        }
        v[j] = min;
        matches[imin]++;
        if (matches[imin] == 1) {
            rowsol[imin] = j;
            colsol[j] = imin;
        } else {
            colsol[j] = -1;
