Actually, a simpler and correct approach: use the "shortest augmenting path" Hungarian algorithm with potentials (the O(n^3) version). This is well-documented and I can write it correctly.

The algorithm:
- We have n rows and n columns, cost matrix c[i][j].
- Maintain potentials u[i] (row) and v[j] (column) such that reduced cost c[i][j] - u[i] - v[j] >= 0.
- Maintain matching: match_col[j] = row matched to column j, or -1.
- For each row i (in order), find augmenting path using Dijkstra-like shortest path on reduced costs.

Standard O(n^3) Hungarian:

```c
void hungarian(int n, const double *c, int *match_col) {
    // match_col[j] = row assigned to column j
    double *u = calloc(n, sizeof(double));
    double *v = calloc(n, sizeof(double));
    int *p = malloc(n * sizeof(int));   // p[j] = row that "points to" column j in alternating tree
    int *way = malloc(n * sizeof(int)); // way[j] = column preceding column j in path
    for (int i = 0; i < n; i++) match_col[i] = -1;

    for (int i = 0; i < n; i++) {
        // find augmenting path from row i
        p[0] = i;
        int j0 = 0;
        double *minv = malloc(n * sizeof(double));
        int *used = calloc(n, sizeof(int));
        for (int j = 0; j < n; j++) minv[j] = INF;
        do {
            used[j0] = 1;
            int i0 = p[j0];
            double delta = INF;
            int j1 = -1;
            for (int j = 1; j < n; j++) {
                if (!used[j]) {
                    double cur = c[i0*n + j] - u[i0] - v[j];
                    if (cur < minv[j]) {
                        minv[j] = cur;
                        way[j] = j0;
                    }
                    if (minv[j] < delta) {
                        delta = minv[j];
                        j1 = j;
                    }
                }
            }
            for (int j = 0; j < n; j++) {
                if (used[j]) {
                    u[p[j]] += delta;
                    v[j] -= delta;
                } else {
                    minv[j] -= delta;
                }
            }
            j0 = j1;
        } while (p[j0] != -1);  // wait, p[j0] is the row matched to column j0
        // augment
        do {
            int j1 = way[j0];
            p[j0] = p[j1];
            j0 = j1;
        } while (j0 != 0);
        // now p[j] for j=1..n-1 gives matching
    }
    for (int j = 1; j < n; j++) {
        if (p[j] != -1) match_col[j] = p[j];
    }
}
```

