```c
#include <stdlib.h>
#include <string.h>
#include <math.h>

#define INF 1e30

int lapjv(int n, const double *cc, int *row_to_col, int *col_to_row) {
    double *u = malloc(n * sizeof(double));
    double *v = malloc(n * sizeof(double));
    double *d = malloc(n * sizeof(double));
    int *pred = malloc(n * sizeof(int));
    int *visited = malloc(n * sizeof(int));
    int *free_rows = malloc(n * sizeof(int));
    int i, j, i0, j1, j2, i1, numfree, f, cnt;
    double min, usubmin, t;

    // initialize
    for (i = 0; i < n; i++) { row_to_col[i] = -1; u[i] = 0; }
    for (j = 0; j < n; j++) { col_to_row[j] = -1; v[j] = 0; }

    // Phase 1: column reduction
    for (j = n - 1; j >= 0; j--) {
        i0 = 0; min = cc[0*n + j];
        for (i = 1; i < n; i++) {
            if (cc[i*n + j] < min) { min = cc[i*n + j]; i0 = i; }
        }
        v[j] = min;
        if (row_to_col[i0] == -1) {
            row_to_col[i0] = j;
            col_to_row[j] = i0;
        } else {
            col_to_row[j] = -1;
        }
    }

    // Phase 2: reduction transfer
    numfree = 0;
    for (i = 0; i < n; i++) {
        if (row_to_col[i] == -1) {
            free_rows[numfree++] = i;
        } else {
            j1 = row_to_col[i];
            min = INF;
            for (j = 0; j < n; j++) {
                if (j != j1) {
                    t = cc[i*n + j] - v[j];
                    if (t < min) min = t;
                }
            }
            u[i] = min;
        }
    }

    // Phase 3: augmenting row reduction (2 passes)
    for (cnt = 0; cnt < 2; cnt++) {
        int k = 0;
        for (i = 0; i < n; i++) {
            if (row_to_col[i] == -1) free_rows[k++] = i;
        }
        numfree = k;
        while (numfree > 0) {
            numfree--;
            i0 = free_rows[numfree];
            j1 = 0; min = cc[i0*n + 0] - v[0];
            for (j = 1; j < n; j++) {
                t = cc[i0*n + j] - v[j];
                if (t < min) { min = t; j1 = j; }
            }
            usubmin = INF;
            for (j = 0; j < n; j++) {
                if (j != j1) {
                    t = cc[i0*n + j] - v[j];
                    if (t < usubmin) usubmin = t;
                }
            }
            u[i0] = usubmin;
            v[j1] -= (usubmin - min);
            if (col_to_row[j1] == -1) {
                col_to_row[j1] = i0;
                row_to_col[i0] = j1;
            } else {
                i1 = col_to_row[j1];
                col_to_row[j1] = i0;
                row_to_col[i0] = j1;
                row_to_col[i1] = -1;
                free_rows[numfree++] = i1;
            }
        }
    }

    // Phase 4: augmenting phase
    for (f = 0; f < numfree; f++) {
        i0 = free_rows[f];
        // Dijkstra
        for (j = 0; j < n; j++) {
            visited[j] = 0;
            pred[j] = i0;
            d[j] = cc[i0*n + j] - u[i0] - v[j];
        }
        j1 = -1;
        while (1) {
            min = INF;
            for (j = 0; j < n; j++) {
                if (!visited[j] && d[j] < min) { min = d[j]; j1 = j; }
            }
            visited[j1] = 1;
            i1 = col_to_row[j1];
            if (i1 == -1) break;
            for (j = 0; j < n; j++) {
                if (!visited[j]) {
                    t = d[j1] + cc[i1*n + j] - u[i1] - v[j];
                    if (t < d[j]) { d[j] = t; pred[j] = i1; }
                }
            }
        }
        // augment
        while (1) {
            i1 = pred[j1];
            col_to_row[j1] = i1;
            t = j1;
            j1 = row_to_col[i1];
            row_to_col[i1] = t;
            if (i1 == i0) break;
        }
        // update duals
        for (j = 0; j < n; j++) {
            if (visited[j]) {
                u[col_to_row[j]] += d[j] - min;
                v[j] -= d[j] - min;
            }
        }
    }

    free(u); free(v); free(d); free(pred); free(visited); free(free_rows);
    return 0;
}
