Actually, the shortest augmenting path algorithm (also called the "successive shortest path" or the O(n^3) Hungarian) is:

```python
def hungarian(cost):
    n = cost.shape[0]
    u = np.zeros(n+1)  # row potentials
    v = np.zeros(n+1)  # col potentials
    p = np.zeros(n+1, dtype=int)  # p[j] = row matched to col j
    way = np.zeros(n+1, dtype=int)
    for i in range(1, n+1):
        p[0] = i
        j0 = 0
        minv = np.full(n+1, np.inf)
        used = np.zeros(n+1, dtype=bool)
        while True:
            used[j0] = True
            i0 = p[j0]
            delta = np.inf
            j1 = 0
            for j in range(1, n+1):
                if not used[j]:
                    cur = cost[i0-1, j-1] - u[i0] - v[j]
                    if cur < minv[j]:
                        minv[j] = cur
                        way[j] = j0
                    if minv[j] < delta:
                        delta = minv[j]
                        j1 = j
            for j in range(n+1):
                if used[j]:
                    u[p[j]] += delta
                    v[j] -= delta
                else:
                    minv[j] -= delta
            j0 = j1
            if p[j0] == 0:
                break
        while True:
            j1 = way[j0]
            p[j0] = p[j1]
            j0 = j1
            if j0 == 0:
                break
    # result
    ans = np.zeros(n+1, dtype=int)
    for j in range(1, n+1):
        ans[p[j]] = j
    return ans[1:] - 1
```

