```c
#include <stdio.h>
#include <stdlib.h>
#include <float.h>

#define BIG DBL_MAX

int* lapjv(double* assigncost, int dim, int* rowsol, int* colsol, double* u, double* v) {
    int i, j, k, imin, j1, j2, i0, numfree, prvnumfree, loopcnt, low, up, last, endofpath;
    double min, h, umin, usubmin, v2, mn;
    int* free = (int*)malloc(dim * sizeof(int));
    int* collist = (int*)malloc(dim * sizeof(int));
    int* matches = (int*)malloc(dim * sizeof(int));
    double* d = (double*)malloc(dim * sizeof(double));
    int* pred = (int*)malloc(dim * sizeof(int));

    for (i = 0; i < dim; i++) {
        matches[i] = 0;
        rowsol[i] = -1;
        colsol[i] = -1;
        u[i] = 0;
        v[i] = 0;
    }

    // column reduction
    for (j = dim - 1; j >= 0; j--) {
        imin = 0;
        min = assigncost[0 * dim + j];
        for (i = 1; i < dim; i++) {
            if (assigncost[i * dim + j] < min) {
                min = assigncost[i * dim + j];
                imin = i;
            }
        }
        v[j] = min;
        matches[imin]++;
        if (matches[imin] == 1) {
            rowsol[imin] = j;
            colsol[j] = imin;
        } else {
            colsol[j] = -1;
        }
    }

    // reduction transfer
    numfree = 0;
    for (i = 0; i < dim; i++) {
        if (matches[i] == 0) {
            free[numfree++] = i;
        } else if (matches[i] == 1) {
            j1 = rowsol[i];
            min = BIG;
            for (j = 0; j < dim; j++) {
                if (j != j1) {
                    if (assigncost[i * dim + j] - v[j] < min) {
                        min = assigncost[i * dim + j] - v[j];
                    }
                }
            }
            v[j1] -= min;
        }
    }

    // augmenting row reduction
    for (loopcnt = 0; loopcnt < 2; loopcnt++) {
        k = 0;
        prvnumfree = numfree;
        numfree = 0;
        while (k < prvnumfree) {
            i = free[k];
            k++;
            umin = assigncost[i * dim + 0] - v[0];
            j1 = 0;
            usubmin = BIG;
            for (j = 1; j < dim; j++) {
                h = assigncost[i * dim + j] - v[j];
                if (h < usubmin) {
                    if (h >= umin) {
                        usubmin = h;
                        j2 = j;
                    } else {
                        usubmin = umin;
                        umin = h;
                        j2 = j1;
                        j1 = j;
                    }
                }
            }
            i0 = colsol[j1];
            if (umin < usubmin) {
                v[j1] -= (usubmin - umin);
            } else {
                if (i0 >= 0) {
                    j1 = j2;
                    i0 = colsol[j2];
                }
            }
            rowsol[i] = j1;
            colsol[j1] = i;
            if (i0 >= 0) {
                if (umin < usubmin) {
                    k--;
                    free[k] = i0;
                } else {
                    free[numfree++] = i0;
                }
            }
        }
    }

    // augmenting path
    for (f = 0; f < numfree; f++) {
        freerow = free[f];
        for (j = 0; j < dim; j++) {
            d[j] = assigncost[freerow * dim + j] - v[j];
            pred[j] = freerow;
            collist[j] = j;
        }
        low = 0; up = 0; unassignedfound = 0;
        while (!unassignedfound) {
            if (up == low) {
                last = low - 1;
                mn = d[collist[up]];
                up++;
                for (k = up; k < dim; k++) {
                    j = collist[k];
                    h = d[j];
                    if (h <= mn) {
                        if (h < mn) {
                            up = low;
                            mn = h;
                        }
                        collist[k] = collist[up];
                        collist[up] = j;
                        up++;
                    }
                }
                for (h = low; h < up; h++) {
                    j = collist[h];
                    if (colsol[j] < 0) {
                        endofpath = j;
                        unassignedfound = 1;
                        break;
                    }
                }
            }
            if (!unassignedfound) {
                j1 = collist[low];
                low++;
                i = colsol[j1];
                h = assigncost[i * dim + j1] - v[j1] - mn;
                for (k = up; k < dim; k++) {
                    j = collist[k];
                    v2 = assigncost[i * dim + j] - v[j] - h;
                    if (v2 < d[j]) {
                        pred[j] = i;
                        d[j] = v2;
                        if (v2 == mn) {
                            if (colsol[j] < 0) {
                                endofpath = j;
                                unassignedfound = 1;
                                break;
                            } else {
                                collist[k] = collist[up];
                                collist[up] = j;
                                up++;
                            }
                        }
                    }
                }
            }
        }
        // update column prices
        for (k = 0; k <= last; k++) {
            j1 = collist[k];
            v[j1] += d[j1] - mn;
        }
        // reset assignments along path
        while (1) {
            i = pred[endofpath];
            colsol[endofpath] = i;
            j1 = endofpath;
            endofpath = rowsol[i];
            rowsol[i] = j1;
            if (i == freerow) break;
        }
    }

    free(free); free(collist); free(matches); free(d); free(pred);
    return rowsol;
}
```

