static int* lapjv(const double* assigncost, int dim, int* rowsol, int* colsol, double* v) {
    int i, j, k, imin, j1, j2, i0, numfree, prvnumfree, loopcnt, low, up, last, endofpath, f, freerow, h;
    double min, hh, umin, usubmin, v2, mn;
    int* free = (int*)malloc(dim * sizeof(int));
    int* collist = (int*)malloc(dim * sizeof(int));
    int* matches = (int*)malloc(dim * sizeof(int));
    double* d = (double*)malloc(dim * sizeof(double));
    int* pred = (int*)malloc(dim * sizeof(int));

    for (i = 0; i < dim; i++) { matches[i] = 0; rowsol[i] = -1; colsol[i] = -1; v[i] = 0; }

    for (j = dim - 1; j >= 0; j--) {
        imin = 0; min = assigncost[j];
        for (i = 1; i < dim; i++) {
            if (assigncost[i*dim + j] < min) { min = assigncost[i*dim + j]; imin = i; }
        }
        v[j] = min;
        matches[imin]++;
        if (matches[imin] == 1) { rowsol[imin] = j; colsol[j] = imin; }
        else colsol[j] = -1;
    }

    numfree = 0;
    for (i = 0; i < dim; i++) {
        if (matches[i] == 0) free[numfree++] = i;
        else if (matches[i] == 1) {
            j1 = rowsol[i]; min = BIG;
            for (j = 0; j < dim; j++) {
                if (j != j1) { if (assigncost[i*dim + j] - v[j] < min) min = assigncost[i*dim + j] - v[j]; }
            }
            v[j1] -= min;
        }
    }

    for (loopcnt = 0; loopcnt < 2; loopcnt++) {
        k = 0; prvnumfree = numfree; numfree = 0;
        while (k < prvnumfree) {
            i = free[k]; k++;
            umin = assigncost[i*dim] - v[0]; j1 = 0; usubmin = BIG; j2 = 0;
            for (j = 1; j < dim; j++) {
                hh = assigncost[i*dim + j] - v[j];
                if (hh < usubmin) {
                    if (hh >= umin) { usubmin = hh; j2 = j; }
                    else { usubmin = umin; umin = hh; j2 = j1; j1 = j; }
                }
            }
            i0 = colsol[j1];
            if (umin < usubmin) v[j1] -= (usubmin - umin);
            else { if (i0 >= 0) { j1 = j2; i0 = colsol[j2]; } }
            rowsol[i] = j1; colsol[j1] = i;
            if (i0 >= 0) {
                if (umin < usubmin) { k--; free[k] = i0; }
                else free[numfree++] = i0;
            }
        }
    }

    for (f = 0; f < numfree; f++) {
        freerow = free[f];
        for (j = 0; j < dim; j++) { d[j] = assigncost[freerow*dim + j] - v[j]; pred[j] = freerow; collist[j] = j; }
        low = 0; up = 0; endofpath = 0; mn = 0;
        int unassignedfound = 0;
        while (!unassignedfound) {
            if (up == low) {
                last = low - 1;
                mn = d[collist[up]]; up++;
                for (k = up; k < dim; k++) {
                    j = collist[k]; hh = d[j];
                    if (hh <= mn) {
                        if (hh < mn) { up = low; mn = hh; }
                        collist[k] = collist[up]; collist[up] = j; up++;
                    }
                }
                for (h = low; h < up; h++) {
                    j = collist[h];
                    if (colsol[j] < 0) { endofpath = j; unassignedfound = 1; break; }
                }
            }
            if (!unassignedfound) {
                j1 = collist[low]; low++;
                i = colsol[j1];
                hh = assigncost[i*dim + j1] - v[j1] - mn;
                for (k = up; k < dim; k++) {
                    j = collist[k];
                    v2 = assigncost[i*dim + j] - v[j] - hh;
                    if (v2 < d[j]) {
                        pred[j] = i; d[j] = v2;
                        if (v2 == mn) {
                            if (colsol[j] < 0) { endofpath = j; unassignedfound = 1; break; }
                            else { collist[k] = collist[up]; collist[up] = j; up++; }
                        }
                    }
                }
            }
        }
        for (k = 0; k <= last; k++) { j1 = collist[k]; v[j1] += d[j1] - mn; }
        while (1) {
            i = pred[endofpath];
            colsol[endofpath] = i;
            j1 = endofpath;
            endofpath = rowsol[i];
            rowsol[i] = j1;
            if (i == freerow) break;
        }
    }

    free(free); free(collist); free(matches); free(d); free(pred);
    return rowsol;
}

int main(int argc, char** argv) {
    int n = atoi(argv[1]);
    int seed = atoi(argv[2]);
    srand(seed);
    double* pts = (double*)malloc(2*n*sizeof(double));
    for (int i = 0; i < 2*n; i++) pts[i] = (double)rand()/RAND_MAX;
    double* cost = (double*)malloc(n*n*sizeof(double));
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++) {
            double dx = pts[2*i]-pts[2*n+2*j];
            double dy = pts[2*i+1]-pts[2*n+2*j+1];
            cost[i*n+j] = sqrt(dx*dx+dy*dy);
        }
    int* rowsol = (int*)malloc(n*sizeof(int));
    int* colsol = (int*)malloc(n*sizeof(int));
    double* v = (double*)malloc(n*sizeof(double));
    struct timespec t0, t1;
    clock_gettime(CLOCK_MONOTONIC, &t0);
    lapjv(cost, n, rowsol, colsol, v);
    clock_gettime(CLOCK_MONOTONIC, &t1);
    double dt = (t1.tv_sec - t0.tv_sec) + (t1.tv_nsec - t0.tv_nsec)/1e9;
    printf("n=%d time=%.6f s\n", n, dt);
    // verify cost
    double total = 0;
    for (int i = 0; i < n; i++) total += cost[i*n + rowsol[i]];
    printf("total cost %.6f\n", total);
    return 0;
}
